WITH filtered AS (SELECT id, customer_id, device, browser, started_at, country, INITCAP(TRIM(browser)) browser_title FROM sessions WHERE started_at > DATE '2023-07-29' AND customer_id IS NOT NULL), prev_events AS (SELECT *, LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) AS prev_started_at FROM filtered), gaps AS (SELECT *, CASE WHEN prev_started_at IS NULL OR started_at > prev_started_at + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM prev_events), sessions_sessions AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT CASE WHEN new_group_flag >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS new_group_flag_tier, country, SUM(CASE WHEN device = 'desktop' THEN new_group_flag ELSE 0 END) AS desktop_new_group_flag, MAX(session_no) FILTER (WHERE device = 'mobile') AS mobile_max_session_no, COUNT(CASE WHEN country = 'US' THEN 1 END) AS us_count, COUNT_IF(device = 'mobile') AS mobile_events, COUNT(*) FILTER (WHERE country = 'JP') AS jp_rows, COUNT(*) FILTER (WHERE device = 'tablet') AS tablet_rows, RANK() OVER (PARTITION BY CASE WHEN new_group_flag >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY COUNT(*) FILTER (WHERE device = 'tablet') DESC) AS tablet_rows_rank FROM sessions_sessions GROUP BY 1, 2;
